# create pattern and bridge
n=30; g=[[0]*n for _ in range(n)]
labels=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# tiles top-left coords 1,8,15,22; color blocks interior
for tr,y in enumerate([1,8,15,22]):
 for tc,x in enumerate([1,8,15,22]):
  for dy in range(5):
   for dx in range(5):
    yy,xx=y+dy,x+dx
    if yy<30 and xx<30: g[yy][xx]=4
  for dy in range(1,4):
   for dx in range(1,4): g[y+dy][x+dx]=labels[tr][tc]
# horizontal bridge gaps for matching labels along row of tiles
for tr,row in enumerate(labels):
 for a in range(4):
  for b in range(a+1,4):
   if row[a]==row[b]:
    for k in range(a,b):
     # gap x= xbase+5,6; center y
     for x in [([1,8,15,22][k]+5),([1,8,15,22][k]+6)]:
      g[[1,8,15,22][tr]+2][x]=row[a]
# vertical bridges
for tc in range(4):
 col=[labels[r][tc] for r in range(4)]
 for a in range(4):
  for b in range(a+1,4):
   if col[a]==col[b]:
    for k in range(a,b):
     for y in [[1,8,15,22][k]+5,[1,8,15,22][k]+6]: g[y][[1,8,15,22][tc]+2]=col[a]
print('\n'.join(','.join(map(str,r)) for r in g))
